<?php
/** Guías contextuales reutilizables para pantallas existentes de ODEA. */
if (!function_exists('odeaRenderAyudaContextual')) {
function odeaAyudaHtml(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
function odeaAyudaData(): ?array
{
    $role=(int)($_SESSION['ROL']??0);$base=defined('BASE_URL')?BASE_URL:'';$page=strtolower(basename(parse_url($_SERVER['SCRIPT_NAME']??'',PHP_URL_PATH)?:''));
    $item=static fn($title,$goal,$before,$steps,$result,$next,$link='',$linkText='',$example='')=>compact('title','goal','before','steps','result','next','link','linkText','example');
    $data=[
      'gestion-usuarios.php'=>$item('Gestión de usuarios','Administra cuentas, roles y estados de acceso.','Necesitas una cuenta administrativa activa. El rol determina las pantallas autorizadas.',['Busca o filtra la cuenta.','Desactiva para conservar evidencias e historial. La eliminación definitiva puede borrar evidencias sin historial, pero se bloquea cuando hay evaluaciones o trazabilidad que deban conservarse.','Comprueba el mensaje de resultado.'],'El listado refleja el estado guardado.','Al crear una cuenta, sigue el procedimiento institucional para comunicar el acceso.'),
      'instrumentos.php'=>$item('Instrumentos','Configura SNII, PRODEP y ESDEPED en ODEA.','Los instrumentos pueden relacionarse con tipos documentales y asignaciones de evaluación.',['Busca antes de crear para evitar duplicados.','Registra abreviatura y nombre institucional.','Desactiva para conservar relaciones e historial; la eliminación definitiva está sujeta a restricciones.'],'El instrumento queda disponible según su estado.','Relaciona tipos documentales y asigna evaluadores cuando corresponda.'),
      'tipos-evidencia.php'=>$item('Tipos de evidencia','Mantiene el catálogo usado al registrar documentos.','Un tipo puede tener atributos propios y asociarse con instrumentos.',['Busca para evitar duplicados.','Registra nombre y descripción.','Abre la gestión de atributos para definir los datos de captura.'],'El tipo aparece en los formularios permitidos.','Configura los atributos desde la acción del registro.'),
      'atributos-tipo.php'=>$item('Atributos del tipo documental','Define los campos descriptivos que se solicitan para este tipo.','Confirma que estás editando el tipo documental correcto.',['Crea el atributo y elige un tipo de dato adecuado.','Marca como requerido solo lo que establezca la configuración institucional.','Guarda y verifica el formulario de evidencia.'],'Los campos aparecen al capturar este tipo documental.','Prueba con datos sintéticos antes de su uso.'),
      'periodos-academicos.php'=>$item('Periodos académicos','Organiza convocatorias por instrumento e intervalo.','El instrumento seleccionado debe corresponder al periodo.',['Selecciona un instrumento.','Registra código y nombre; define fechas cuando apliquen.','Guarda y selecciona este periodo al crear una convocatoria.'],'El periodo queda asociado al instrumento indicado.','Continúa en Convocatorias.',$base.'/views/admin/convocatorias.php','Ir a Convocatorias','Código PRODEP-2026; nombre Periodo académico PRODEP 2026. Ejemplo ilustrativo, no oficial.'),
      'convocatorias.php'=>$item('Convocatorias','Organiza procesos académicos asociados a un instrumento y periodo.','El periodo debe pertenecer al mismo instrumento. Una convocatoria nueva comienza en borrador.',['Selecciona instrumento y periodo compatibles.','Completa los datos generales y guarda.','Configura una versión de criterios y sus fuentes normativas.','Publica la versión y vuelve aquí para activar.'],'La activación requiere una versión publicada y válida.','Configura los criterios antes de activar.',$base.'/views/admin/criterios-evaluacion.php','Ir a Criterios de Evaluación','CONV-2026-01 es solo un ejemplo, no una convocatoria oficial.'),
      'criterios-evaluacion.php'=>$item('Criterios de evaluación','Configura versiones, categorías, criterios, subcriterios y requisitos.','Selecciona instrumento y convocatoria. Solo se editan versiones en borrador.',['Crea una versión.','Agrega categoría y criterio.','Configura requisitos que estén respaldados.','Registra fuentes normativas, valídalas y relaciónalas con criterios.','Publica cuando se cumplan las validaciones.'],'La versión publicada queda protegida contra edición directa.','Después de publicar, vuelve a Convocatorias para activar.',$base.'/views/admin/convocatorias.php','Volver a Convocatorias','Ejemplos: versión 1.0, categoría CAT-INV, criterio CRIT-ART. No son reglas oficiales.'),
      'fuentes-normativas.php'=>$item('Fuentes normativas','Registra los documentos que fundamentan criterios de una versión.','La versión debe estar en borrador. Cada criterio debe tener una fuente validada para publicar.',['Selecciona la versión.','Registra nombre y referencia del documento.','Valida solo después de revisar la fuente.','Relaciona la fuente con cada criterio que fundamenta.'],'El sistema registra responsable y fecha de validación.','Revisa las relaciones antes de publicar.',$base.'/views/admin/criterios-evaluacion.php','Ir a Criterios'),
      'gestion-evidencias.php'=>$item('Gestión de evidencias',$role===3?'Consulta evidencias de instrumentos asignados.':'Registra y consulta evidencias según tu rol.','Para cargar, selecciona tipo documental y completa los campos requeridos. La pantalla indica formatos y límites.',['Selecciona Agregar evidencia si está disponible.','Elige el tipo documental y completa sus atributos.','Adjunta el archivo y guarda.','Abre el detalle para consultar procesamiento y resultados.'],'La carga no equivale a una aprobación académica.','Revisa el detalle y atiende observaciones.'),
      'evaluacion.php'=>$item('Evaluación de evidencias','Revisa evidencias dentro de tus instrumentos asignados.','Se muestran registros con los campos obligatorios completos y dentro del alcance autorizado.',['Busca por título, docente o tipo.','Consulta el documento y sus datos.','Registra decisión y observaciones usando las opciones habilitadas.','Consulta el historial de la revisión.'],'La decisión se guarda asociada a su historial.','Si falta una evidencia, revisa filtros, requisitos y asignaciones.'),
      'expediente.php'=>$item('Expediente académico','Consulta evidencias e historial que tu rol tiene permitido ver.','El docente consulta su propio expediente; otras consultas dependen de permisos.',['Revisa datos y evidencias.','Filtra por instrumento si está disponible.','Abre el detalle para documentos y evaluaciones.'],'Se muestran registros existentes; un estado vacío significa que no hay datos disponibles.','Para agregar documentos, abre Gestión de evidencias.',$base.'/views/docente/gestion-evidencias.php','Ir a Gestión de evidencias'),
      'revision-metadatos.php'=>$item('Revisión de metadatos','Compara datos sugeridos por la extracción con el documento original.','La extracción puede equivocarse. Confirmar un campo no autentica ni aprueba el archivo.',['Compara cada valor con el original.','Corrige, confirma o rechaza las sugerencias.','Guarda la revisión.'],'La revisión humana conserva valores y estados.','Vuelve al listado para consultar el estado.',$base.'/views/docente/gestion-evidencias.php','Volver a evidencias'),
      'aplicaciones-academicas.php'=>$item('Aplicaciones académicas sugeridas','Consulta propuestas de relación con criterios configurados por convocatoria.','Las propuestas dependen de metadatos y reglas existentes, y requieren revisión humana.',['Ejecuta las reglas si la acción está disponible.','Revisa justificación, requisitos y fuente.','Confirma o rechaza cuando esas acciones estén habilitadas.'],'Una coincidencia no es dictamen oficial ni aprobación.','Consulta la convocatoria y versión asociadas.'),
      'calificaciones-recibidas.php'=>$item('Resultados recibidos','Consulta evaluaciones y observaciones de tus evidencias.','Solo se muestran resultados disponibles para tu cuenta.',['Filtra los registros.','Abre el detalle para leer observaciones e historial.','Atiende correcciones según el flujo habilitado.'],'Los resultados reflejan decisiones registradas.','Consulta tus documentos en Gestión de evidencias.',$base.'/views/docente/gestion-evidencias.php','Ir a Gestión de evidencias'),
      'evidencia-detalle.php'=>$item('Detalle de evidencia','Consulta archivo, atributos, procesamiento y resultados disponibles.','El acceso depende de propiedad, rol y asignaciones.',['Verifica archivo y datos.','Consulta procesamiento y evaluación.','Usa las acciones permitidas para tu rol.'],'El detalle muestra el estado actual del registro.','Vuelve al listado para continuar.',$base.'/views/docente/gestion-evidencias.php','Volver a evidencias'),
      'permisos-instrumentos.php'=>$item('Asignaciones de instrumentos','Consulta las asignaciones que delimitan el trabajo evaluador.','Las acciones de administración requieren permiso autorizado.',['Selecciona el evaluador o instrumento disponible.','Revisa la asignación antes de cambiarla.','Guarda y comprueba el resultado.'],'Las asignaciones controlan el alcance de consulta.','El evaluador puede continuar desde su bandeja.'),
      'campos-instrumentos-evaluador.php'=>$item('Campos del instrumento','Consulta la configuración de campos disponible para el instrumento.','Verifica el instrumento y las opciones que presenta esta pantalla.',['Revisa los campos vinculados.','Cambia únicamente opciones habilitadas para tu rol.','Guarda si la pantalla ofrece esa acción.'],'Los cambios permitidos se reflejan en el flujo relacionado.','Vuelve a la evaluación para revisar su aplicación.'),
      'perfil.php'=>$item('Perfil','Consulta la información de tu cuenta.','Solo se pueden cambiar los campos habilitados.',['Revisa tus datos.','Edita los campos disponibles.','Guarda y verifica la confirmación.'],'El perfil refleja los datos de la cuenta.','Vuelve al panel para continuar.'),
      'perfil-usuario.php'=>$item('Perfil','Consulta la información de tu cuenta.','Solo se pueden cambiar los campos habilitados.',['Revisa tus datos.','Edita los campos disponibles.','Guarda y verifica la confirmación.'],'El perfil refleja los datos de la cuenta.','Vuelve al panel para continuar.'),
    ];
    if($page==='index.php'){
      if(in_array($role,[1,2],true))$data[$page]=$item('Panel administrativo','Consulta indicadores agregados y accesos administrativos.','Los totales dependen de los registros existentes y módulos instalados.',['Revisa indicadores y estados.','Abre el módulo correspondiente para gestionar.','Usa los filtros disponibles.'],'Las cifras resumen los datos existentes.','Elige una opción del menú según tu tarea.');
      elseif($role===3)$data[$page]=$item('Panel del evaluador','Resume asignaciones, bandeja e historial dentro de tus instrumentos.','La información se limita a tus asignaciones.',['Revisa pendientes y revisadas.','Abre la bandeja de evidencias.','Consulta el historial.'],'Solo se muestran datos dentro de tu alcance.','Abre Evaluación para comenzar.',$base.'/views/evaluador/evaluacion.php','Ir a Evaluación');
      elseif($role===4)$data[$page]=$item('Panel del docente','Resume tus evidencias e información por instrumento.','Se muestran tus registros existentes.',['Revisa totales por instrumento.','Consulta estados recientes.','Abre expediente o carga evidencia.'],'La cobertura describe documentos registrados; no predice reconocimientos.','Usa Gestión de evidencias.',$base.'/views/docente/gestion-evidencias.php','Ir a Gestión de evidencias');
    }
    if(in_array($role,[3,4],true)&&in_array($page,['gestion-usuarios.php','instrumentos.php','tipos-evidencia.php','atributos-tipo.php','periodos-academicos.php','convocatorias.php','criterios-evaluacion.php','fuentes-normativas.php'],true))return null;
    if(in_array($role,[3,4],true)&&in_array($page,['permisos-instrumentos.php'],true))return null;
    return $data[$page]??null;
}
function odeaRenderAyudaContextual(): void
{
    if(empty($_SESSION['SESUSUARIO']))return;$help=odeaAyudaData();if(!$help)return;
    echo '<aside class="odea-context-help" aria-label="Ayuda contextual"><details><summary><span aria-hidden="true">?</span> ¿Cómo utilizar este apartado?</summary><div class="odea-context-help__panel"><h2>'.odeaAyudaHtml($help['title']).'</h2><p>'.odeaAyudaHtml($help['goal']).'</p><h3>Antes de comenzar</h3><p>'.odeaAyudaHtml($help['before']).'</p><h3>Pasos</h3><ol>';foreach($help['steps'] as $step)echo '<li>'.odeaAyudaHtml($step).'</li>';echo '</ol><h3>Resultado esperado</h3><p>'.odeaAyudaHtml($help['result']).'</p><p><strong>Siguiente paso:</strong> '.odeaAyudaHtml($help['next']).'</p>';if($help['example']!=='')echo '<p class="odea-context-help__example"><strong>Ejemplo ilustrativo:</strong> '.odeaAyudaHtml($help['example']).'</p>';if($help['link']!=='')echo '<a class="btn" href="'.odeaAyudaHtml($help['link']).'">'.odeaAyudaHtml($help['linkText']).'</a>';echo '</div></details></aside>';
}
}
odeaRenderAyudaContextual();
if(!empty($_SESSION['SESUSUARIO'])):
?>
