<script>
(()=>{const examples={codigo:'Ej. CONV-2026-01',nombre:'Ej. Nombre descriptivo',descripcion:'Describe el propósito y alcance de este registro.',doi:'Ej. 10.1234/ejemplo.2026.001',issn:'Ej. 1234-5678',isbn:'Ej. 978-0-00-000000-0',horas:'Ej. 40',institucion:'Ej. Institución emisora del documento',duracion:'Ej. 40'};document.querySelectorAll('input:not([type=hidden]),textarea').forEach(el=>{if(el.placeholder)return;const key=(el.name+' '+el.id+' '+(el.closest('label')?.innerText||'')).toLowerCase();for(const [match,value] of Object.entries(examples))if(key.includes(match)){el.placeholder=value;break;}});const hints={id_version:'Identifica el conjunto de reglas de una convocatoria. Las versiones publicadas conservan la configuración usada en evaluaciones.',obligatorio:'Marca obligatoriedad solo cuando esté definida por una regla institucional validada.',id_fuente:'Documento oficial o institucional que fundamenta el criterio. Valídalo solo después de revisar su referencia.',estado:'Borrador indica preparación; Publicada protege la versión. El estado disponible depende del flujo de esta pantalla.'};const academicPage=['periodos-academicos.php','convocatorias.php','criterios-evaluacion.php','fuentes-normativas.php'].includes(location.pathname.split('/').pop());document.querySelectorAll('input,select,textarea').forEach(el=>{const text=el.name==='estado'&&!academicPage?'':hints[el.name];if(!text||!el.closest('label')||el.parentElement.querySelector('.odea-field-help'))return;const details=document.createElement('details');details.className='odea-field-help';const summary=document.createElement('summary');summary.textContent='¿Qué significa?';const content=document.createElement('span');content.textContent=text;details.append(summary,content);el.closest('label').append(details);});const emptyCopy={'gestion-usuarios.php':'No hay usuarios que coincidan. Ajusta la búsqueda o usa Agregar usuario para crear una cuenta.','instrumentos.php':'No hay instrumentos para mostrar. Ajusta los filtros o agrega un instrumento autorizado.','tipos-evidencia.php':'No hay tipos de evidencia para mostrar. Ajusta la búsqueda o agrega un tipo documental.','gestion-evidencias.php':'No hay evidencias para estos filtros. Si tienes permiso de carga, usa Agregar evidencia para iniciar.','evaluacion.php':'No hay evidencias para estos filtros o asignaciones. Revisa los instrumentos asignados y los campos documentales requeridos.','calificaciones-recibidas.php':'No hay resultados para mostrar. Revisa los filtros o vuelve a consultar más adelante.'};const message=emptyCopy[location.pathname.split('/').pop()];if(message){const update=()=>document.querySelectorAll('td.dataTables_empty').forEach(el=>{if(el.textContent!==message)el.textContent=message;});update();new MutationObserver(update).observe(document.body,{childList:true,subtree:true});}})();
</script>
<?php endif; ?>
